-- Esquema completo de Ordanza POS para la versión local.
-- Debe coincidir con prisma/schema.prisma. Cada cambio de esquema = un archivo nuevo (002_..., 003_...).
CREATE TYPE "Rol" AS ENUM ('ADMIN','CAJERO','ALMACEN');
CREATE TYPE "TurnoEstado" AS ENUM ('ABIERTO','CERRADO');
CREATE TYPE "MovTipo" AS ENUM ('INICIAL','ENTRADA','SALIDA','AJUSTE','VENTA','CANCELACION','DEVOLUCION','COMPRA');
CREATE TYPE "MetodoPago" AS ENUM ('EFECTIVO','TARJETA','TRANSFERENCIA','CREDITO');
CREATE TYPE "VentaEstado" AS ENUM ('PAGADA','CANCELADA');
CREATE TYPE "CitaEstado" AS ENUM ('PENDIENTE','HECHA','CANCELADA');
CREATE TABLE "Tenant"(id text PRIMARY KEY, slug text NOT NULL UNIQUE, nombre text NOT NULL, rfc text, direccion text, telefono text, "piePagina" text NOT NULL DEFAULT '¡Gracias por su compra!', "anchoTicket" int NOT NULL DEFAULT 58, "ivaPct" decimal(5,2) NOT NULL DEFAULT 16, "permitirSinStock" boolean NOT NULL DEFAULT false, "zonaHoraria" text NOT NULL DEFAULT 'America/Mexico_City', activo boolean NOT NULL DEFAULT true, creado timestamp(3) NOT NULL DEFAULT now());
CREATE TABLE "Usuario"(id text PRIMARY KEY, "tenantId" text NOT NULL REFERENCES "Tenant"(id) ON DELETE CASCADE, nombre text NOT NULL, email text UNIQUE, "passwordHash" text, "pinHash" text NOT NULL, rol "Rol" NOT NULL DEFAULT 'CAJERO', activo boolean NOT NULL DEFAULT true, "intentosFallidos" int NOT NULL DEFAULT 0, "bloqueadoHasta" timestamp(3), creado timestamp(3) NOT NULL DEFAULT now());
CREATE TABLE "Caja"(id text PRIMARY KEY, "tenantId" text NOT NULL REFERENCES "Tenant"(id) ON DELETE CASCADE, nombre text NOT NULL, clave text NOT NULL, activa boolean NOT NULL DEFAULT true, consecutivo int NOT NULL DEFAULT 0, UNIQUE("tenantId",clave));
CREATE TABLE "Turno"(id text PRIMARY KEY, "tenantId" text NOT NULL REFERENCES "Tenant"(id) ON DELETE CASCADE, "cajaId" text NOT NULL REFERENCES "Caja"(id), estado "TurnoEstado" NOT NULL DEFAULT 'ABIERTO', "abiertoPorId" text NOT NULL, "abiertoPor" text NOT NULL, "abiertoEn" timestamp(3) NOT NULL DEFAULT now(), fondo decimal(12,2) NOT NULL, "cerradoPorId" text, "cerradoPor" text, "cerradoEn" timestamp(3), esperado decimal(12,2), contado decimal(12,2), diferencia decimal(12,2), nota text);
CREATE TABLE "Categoria"(id text PRIMARY KEY, "tenantId" text NOT NULL REFERENCES "Tenant"(id) ON DELETE CASCADE, nombre text NOT NULL, UNIQUE("tenantId",nombre));
CREATE TABLE "Producto"(id text PRIMARY KEY, "tenantId" text NOT NULL REFERENCES "Tenant"(id) ON DELETE CASCADE, nombre text NOT NULL, codigo text, sku text, "categoriaId" text REFERENCES "Categoria"(id) ON DELETE SET NULL, unidad text NOT NULL DEFAULT 'pza', "esServicio" boolean NOT NULL DEFAULT false, precio decimal(12,2) NOT NULL, costo decimal(12,2) NOT NULL DEFAULT 0, minimo decimal(12,3) NOT NULL DEFAULT 0, proveedor text, ubicacion text, "fotoUrl" text, activo boolean NOT NULL DEFAULT true, creado timestamp(3) NOT NULL DEFAULT now(), actualizado timestamp(3) NOT NULL, UNIQUE("tenantId",codigo));
CREATE TABLE "Venta"(id text PRIMARY KEY, "tenantId" text NOT NULL REFERENCES "Tenant"(id) ON DELETE CASCADE, folio text NOT NULL, "clientId" text NOT NULL UNIQUE, "cajaId" text NOT NULL REFERENCES "Caja"(id), "turnoId" text NOT NULL REFERENCES "Turno"(id), "usuarioId" text NOT NULL, "usuarioNombre" text NOT NULL, cliente text, subtotal decimal(12,2) NOT NULL, descuento decimal(12,2) NOT NULL DEFAULT 0, iva decimal(12,2) NOT NULL, total decimal(12,2) NOT NULL, costo decimal(12,2) NOT NULL, metodo "MetodoPago" NOT NULL, recibido decimal(12,2) NOT NULL, cambio decimal(12,2) NOT NULL, estado "VentaEstado" NOT NULL DEFAULT 'PAGADA', "canceladaPor" text, "canceladaEn" timestamp(3), "motivoCancelacion" text, creado timestamp(3) NOT NULL DEFAULT now(), UNIQUE("tenantId",folio));
CREATE TABLE "Movimiento"(id text PRIMARY KEY, "tenantId" text NOT NULL REFERENCES "Tenant"(id) ON DELETE CASCADE, "productoId" text NOT NULL REFERENCES "Producto"(id) ON DELETE CASCADE, tipo "MovTipo" NOT NULL, cantidad decimal(12,3) NOT NULL, "costoUnit" decimal(12,2), nota text, "usuarioId" text NOT NULL, "usuarioNombre" text NOT NULL, "ventaId" text, creado timestamp(3) NOT NULL DEFAULT now());
CREATE TABLE "VentaItem"(id text PRIMARY KEY, "ventaId" text NOT NULL REFERENCES "Venta"(id) ON DELETE CASCADE, "productoId" text NOT NULL REFERENCES "Producto"(id), nombre text NOT NULL, unidad text NOT NULL, precio decimal(12,2) NOT NULL, costo decimal(12,2) NOT NULL, cantidad decimal(12,3) NOT NULL, importe decimal(12,2) NOT NULL);
CREATE TABLE "Cita"(id text PRIMARY KEY, "tenantId" text NOT NULL REFERENCES "Tenant"(id) ON DELETE CASCADE, titulo text NOT NULL, fecha text NOT NULL, hora text, cliente text, telefono text, nota text, estado "CitaEstado" NOT NULL DEFAULT 'PENDIENTE', "creadoPor" text NOT NULL, creado timestamp(3) NOT NULL DEFAULT now());
CREATE TABLE "Bitacora"(id text PRIMARY KEY, "tenantId" text NOT NULL REFERENCES "Tenant"(id) ON DELETE CASCADE, "usuarioId" text, "usuarioNombre" text NOT NULL, modulo text NOT NULL, accion text NOT NULL, detalle text, creado timestamp(3) NOT NULL DEFAULT now());
CREATE TYPE "MovCajaTipo" AS ENUM ('ENTRADA','RETIRO');
CREATE TYPE "MovClienteTipo" AS ENUM ('CARGO','ABONO');
ALTER TABLE "Tenant" ADD "autorizarDescuento" boolean NOT NULL DEFAULT true, ADD "autorizarRetiro" boolean NOT NULL DEFAULT true, ADD "autorizarDevolucion" boolean NOT NULL DEFAULT true, ADD plan text NOT NULL DEFAULT 'Básico', ADD "maxCajas" int NOT NULL DEFAULT 2, ADD "pagadoHasta" timestamp(3), ADD "notasOrdanza" text, ADD "licenciaClave" text;
ALTER TABLE "Movimiento" ADD "compraId" text, ADD "devolucionId" text;
CREATE TABLE "Cliente"(id text PRIMARY KEY, "tenantId" text NOT NULL REFERENCES "Tenant"(id) ON DELETE CASCADE, nombre text NOT NULL, telefono text, email text, rfc text, "limiteCredito" decimal(12,2) NOT NULL DEFAULT 0, nota text, activo boolean NOT NULL DEFAULT true, creado timestamp(3) NOT NULL DEFAULT now());
ALTER TABLE "Venta" ADD "clienteId" text REFERENCES "Cliente"(id) ON DELETE SET NULL, ADD "autorizadoPor" text;
ALTER TABLE "VentaItem" ADD devuelto decimal(12,3) NOT NULL DEFAULT 0;
CREATE TABLE "VentaPago"(id text PRIMARY KEY, "ventaId" text NOT NULL REFERENCES "Venta"(id) ON DELETE CASCADE, metodo "MetodoPago" NOT NULL, monto decimal(12,2) NOT NULL);
CREATE TABLE "MovCliente"(id text PRIMARY KEY, "tenantId" text NOT NULL REFERENCES "Tenant"(id) ON DELETE CASCADE, "clienteId" text NOT NULL REFERENCES "Cliente"(id) ON DELETE CASCADE, tipo "MovClienteTipo" NOT NULL, monto decimal(12,2) NOT NULL, metodo "MetodoPago", "ventaId" text, "turnoId" text, nota text, "usuarioId" text NOT NULL, "usuarioNombre" text NOT NULL, creado timestamp(3) NOT NULL DEFAULT now());
CREATE TABLE "MovCaja"(id text PRIMARY KEY, "tenantId" text NOT NULL REFERENCES "Tenant"(id) ON DELETE CASCADE, "turnoId" text NOT NULL REFERENCES "Turno"(id) ON DELETE CASCADE, tipo "MovCajaTipo" NOT NULL, monto decimal(12,2) NOT NULL, concepto text NOT NULL, "compraId" text, "usuarioId" text NOT NULL, "usuarioNombre" text NOT NULL, "autorizadoPor" text, creado timestamp(3) NOT NULL DEFAULT now());
CREATE TABLE "Devolucion"(id text PRIMARY KEY, "tenantId" text NOT NULL REFERENCES "Tenant"(id) ON DELETE CASCADE, "ventaId" text NOT NULL REFERENCES "Venta"(id) ON DELETE CASCADE, "turnoId" text, total decimal(12,2) NOT NULL, metodo "MetodoPago" NOT NULL, motivo text NOT NULL, "usuarioId" text NOT NULL, "usuarioNombre" text NOT NULL, "autorizadoPor" text, creado timestamp(3) NOT NULL DEFAULT now());
CREATE TABLE "DevolucionItem"(id text PRIMARY KEY, "devolucionId" text NOT NULL REFERENCES "Devolucion"(id) ON DELETE CASCADE, "ventaItemId" text NOT NULL, "productoId" text NOT NULL, nombre text NOT NULL, cantidad decimal(12,3) NOT NULL, importe decimal(12,2) NOT NULL);
CREATE TABLE "Proveedor"(id text PRIMARY KEY, "tenantId" text NOT NULL REFERENCES "Tenant"(id) ON DELETE CASCADE, nombre text NOT NULL, contacto text, telefono text, email text, rfc text, nota text, activo boolean NOT NULL DEFAULT true, creado timestamp(3) NOT NULL DEFAULT now(), UNIQUE("tenantId",nombre));
CREATE TABLE "Compra"(id text PRIMARY KEY, "tenantId" text NOT NULL REFERENCES "Tenant"(id) ON DELETE CASCADE, "proveedorId" text REFERENCES "Proveedor"(id) ON DELETE SET NULL, factura text, total decimal(12,2) NOT NULL, nota text, "pagadoDeCaja" boolean NOT NULL DEFAULT false, "usuarioId" text NOT NULL, "usuarioNombre" text NOT NULL, creado timestamp(3) NOT NULL DEFAULT now());
CREATE TABLE "CompraItem"(id text PRIMARY KEY, "compraId" text NOT NULL REFERENCES "Compra"(id) ON DELETE CASCADE, "productoId" text NOT NULL REFERENCES "Producto"(id), nombre text NOT NULL, cantidad decimal(12,3) NOT NULL, costo decimal(12,2) NOT NULL, importe decimal(12,2) NOT NULL);

CREATE INDEX ON "Usuario"("tenantId");
CREATE INDEX ON "Turno"("tenantId","cajaId",estado);
CREATE INDEX ON "Producto"("tenantId",nombre);
CREATE INDEX ON "Movimiento"("tenantId","productoId");
CREATE INDEX ON "Movimiento"("tenantId",creado);
CREATE INDEX ON "Venta"("tenantId",creado);
CREATE INDEX ON "Venta"("turnoId");
CREATE INDEX ON "VentaItem"("ventaId");
CREATE INDEX ON "VentaPago"("ventaId");
CREATE INDEX ON "Cliente"("tenantId",nombre);
CREATE INDEX ON "MovCliente"("tenantId","clienteId");
CREATE INDEX ON "MovCliente"("turnoId");
CREATE INDEX ON "MovCaja"("turnoId");
CREATE INDEX ON "Devolucion"("tenantId",creado);
CREATE INDEX ON "Devolucion"("turnoId");
CREATE INDEX ON "Compra"("tenantId",creado);
CREATE INDEX ON "Cita"("tenantId",fecha);
CREATE INDEX ON "Bitacora"("tenantId",creado);
